insert into public.parking_spot (id, venue_id, name, kind, address, operator, location, distance_m, open_on_matchdays, price_note, note, sources, confidence, checked_on, created_at, source, osm_id, capacity) values
  ('8ae9d5fd-3a51-494a-83fd-7e181adc7c04', 'dragao', 'Parque Metro – Estação Estádio do Dragão', 'park_and_ride', 'Alameda das Antas, 4350-415 Porto', 'Telpark (Empark Portugal)', '0101000020E61000009F1B3FF9602A21C0255987A3AB944440', 93, true, 'Tarifa normal: 0,50 € por cada 15 min, máximo de 20 € por 24 h. Em dia de jogo, quem entra a menos de 4 h do início paga tarifa única: 10 € (1.ª Liga e Taça de Portugal) ou 15 € (jogos internacionais e finais). Quem entra antes das 4 h pag…', '850 lugares, subterrâneo, aberto 24 h, com ligação coberta à estação de metro. Em 2019, o FC Porto vendia aos sócios um cartão de época (150 €) para estacionar aqui em dias de jogo; não se encontrou confirmação atual.', '[{"published": null, "title": "Metro do Porto / Park & Ride", "url": "https://www.metrodoporto.pt/pages/298"}, {"published": "2026", "title": "Tarifário Empark Dragão (Parque Metro Estação Estádio do Dragão)", "url": "https://www.metrodoporto.pt/metrodoporto/uploads/writer_file/document/767/tarifario_empark_dragao_ago2026.pdf"}, {"published": null, "title": "Parque Metro - Estación Estádio do Dragão, Porto | Telpark", "url": "https://www.telpark.com/en/cities/porto/metro-estacion-estadio-do-dragao-car-park/"}, {"published": "2019-08-21", "title": "FC Porto - Notícias - Lugares disponíveis no Parque do Metro", "url": "https://www.fcporto.pt/pt/noticias/20190821-pt-lugares-disponiveis-no-parque-do-metro"}]', 'high', '2026-09-15', '2026-09-15 21:01:54.255039+00', 'pesquisa', null, null),
  ('c2fc9de9-97a1-466d-9d5c-67a21f101042', 'afonso-henriques', 'Parque Central Estádio', 'parque_publico', 'Rua João XXI, Guimarães', 'Vitrus Ambiente', null, null, null, null, '269 lugares, aberto 24 h. Num jogo da Seleção em 2018, a alameda junto ao estádio foi interditada, mas manteve-se o acesso a este parque.', '[{"published": null, "title": "Parques de Estacionamento Públicos | Agenda Cultural de Guimarães", "url": "https://em.guimaraes.pt/geo_artigo-28/parques-de-estacionamento-publicos"}, {"published": "2018", "title": "Circulação e estacionamento interditos junto ao Estádio D. Afonso Henriques - Mais Guimarães", "url": "https://maisguimaraes.pt/circulacao-e-estacionamento-interditos-junto-ao-estadio-d-afonso-henriques/"}]', 'medium', '2026-09-15', '2026-09-15 21:01:54.255039+00', 'pesquisa', null, null),
  ('4681fead-c169-4923-93dc-9a84a654ce4c', 'afonso-henriques', 'Imediações da Esquadra da PSP de Guimarães (adeptos visitantes)', 'rua', 'Zona da Esquadra/Divisão Policial da PSP, Guimarães', null, null, null, true, null, 'Por indicação das forças de segurança, recomendado aos adeptos da equipa visitante que vão de carro. Em 2024, o FC Porto marcou o ponto de encontro dos seus adeptos na Rua do Pombal, nas traseiras da Divisão Policial.', '[{"published": "2025", "title": "Guia do Adepto 2025/2026 - Vitória SC (Liga Portugal)", "url": "https://ligaportugalstorage.blob.core.windows.net/backoffice/assets/Guia_do_Adepto_VSC_36368e8c3e.pdf"}, {"published": "2024-09-20", "title": "FC Porto - Notícias - Informações aos adeptos que vão a Guimarães", "url": "https://www.fcporto.pt/pt/noticias/20240920-pt-informacoes-aos-adeptos-que-vao-a-guimaraes"}]', 'medium', '2026-09-15', '2026-09-15 21:01:54.255039+00', 'pesquisa', null, null),
  ('0cdbec93-c5f1-46e8-88c7-29caf77d55be', 'municipal-braga', 'Zona da Porta 3 (adeptos visitantes)', 'rua', 'Acesso pela Estrada de São Martinho e Rua António José Lisboa, Braga', null, null, null, true, null, 'Indicação dada aos adeptos do FC Porto num jogo de março de 2026, com vigilância da PSP. Pode mudar de jogo para jogo.', '[{"published": "2026-03-21", "title": "FC Porto - Notícias - Informações aos adeptos que vão a Braga", "url": "https://www.fcporto.pt/pt/noticias/20260321-pt-informacoes-aos-adeptos-que-vao-a-braga"}]', 'medium', '2026-09-15', '2026-09-15 21:01:54.255039+00', 'pesquisa', null, null),
  ('1322354f-aa0e-4caa-bb0c-a238f3777f79', 'municipal-braga', 'Parque de autocarros dos adeptos visitantes', 'parque_oficial', 'Junto à bancada visitante, Estádio Municipal de Braga', 'SC Braga', null, null, null, null, 'Só para autocarros de adeptos visitantes (não serve carros particulares). O SC Braga anunciou em 2025 um parque novo para 30 autocarros.', '[{"published": "2025-06-14", "title": "Sp. Braga reposiciona adeptos visitantes e investe 1 M€ num novo parque de estacionamento - Record", "url": "https://www.record.pt/futebol/futebol-nacional/liga-betclic/sp--braga/detalhe/sp-braga-reposiciona-adeptos-visitantes-e-investe-1-m-num-novo-parque-de-estacionamento"}, {"published": null, "title": "Guia do Adepto - Estádio Municipal de Braga (Liga Portugal)", "url": "https://ligaportugalstorage.blob.core.windows.net/backoffice/assets/Guia_Adepto_SC_Braga_d6bdc1a8e8.pdf"}]', 'medium', '2026-09-15', '2026-09-15 21:01:54.255039+00', 'pesquisa', null, null),
