  ('980d391a-958b-4037-98df-659989ab23b4', 'luz', 'Parque EMEL Cosme Damião', 'parque_publico', 'Av. Machado dos Santos, Lisboa', 'EMEL', '0101000020E61000001DF11AAA185D22C0B5E78DEE7B604340', 277, null, 'Tarifa geral publicada pela EMEL: 0,80 € por 1 hora. Não há tarifa própria para dias de jogo.', 'Parque em estrutura com 287 lugares, aberto 24 horas. O guia do Benfica sugere parques EMEL próximos do estádio. Em eventos grandes pode haver lugares reservados na Praça Cosme Damião/parque EMEL (aconteceu num concerto em junho de 2025).', '[{"published": null, "title": "Cosme Damião - EMEL", "url": "https://www.emel.pt/pt/parques/cosme-damiao/"}, {"published": "2025", "title": "Guia do Adepto 25/26 – SL Benfica (Liga Portugal)", "url": "https://ligaportugalstorage.blob.core.windows.net/backoffice/assets/Documento_Guia_do_Adepto_SLB_8dca774e3f.pdf"}, {"published": "2025-06-04", "title": "Trânsito e estacionamento condicionados junto ao Estádio da Luz entre quinta e domingo - Renascença", "url": "https://rr.pt/noticia/pais/2025/06/04/transito-e-estacionamento-condicionados-junto-ao-estadio-da-luz-entre-quinta-e-domingo/428076/"}]', 'medium', '2026-09-15', '2026-09-15 21:01:54.255039+00', 'pesquisa', null, null),
