insert into public.venue_parking (venue_id, summary, summary_sources, warnings, checked_on) values
  ('dragao', 'O parque do Metro junto ao estádio (850 lugares, 24 horas) aplica uma tarifa única em dia de jogo a quem entra a menos de 4 horas do início. A PSP recomenda ir de transportes públicos e, de carro, usar os parques destinados ao efeito.', '[{"published": null, "title": "Metro do Porto / Park & Ride", "url": "https://www.metrodoporto.pt/pages/298"}, {"published": "2026-04-22", "title": "\"Rumo ao Jamor\". Se vai hoje ao Dragão, PSP tem recomendações: \"Civismo\" - Notícias ao Minuto", "url": "https://www.noticiasaominuto.com/pais/2977544/rumo-ao-jamor-se-vai-hoje-ao-dragao-psp-tem-recomendacoes-civismo"}]', '[{"sources": [{"published": "2026-04-22", "title": "\"Rumo ao Jamor\". Se vai hoje ao Dragão, PSP tem recomendações: \"Civismo\" - Notícias ao Minuto", "url": "https://www.noticiasaominuto.com/pais/2977544/rumo-ao-jamor-se-vai-hoje-ao-dragao-psp-tem-recomendacoes-civismo"}], "text": "Em jogos grandes, a PSP avisa que o trânsito junto ao estádio fica condicionado a partir do fim da tarde e recomenda ir de transportes públicos. Quem for de carro deve usar os parques destinados ao efeito."}]', '2026-09-15'),
  ('afonso-henriques', 'Junto ao estádio há o Parque Central Estádio (269 lugares, 24 h), gerido pela Vitrus. O guia do adepto 2025/26 aconselha os adeptos visitantes que vão de carro a estacionar perto da Esquadra da PSP, e o clube tem o autocarro Rota do Rei (1 €, ida e volta) a partir de várias zonas do concelho.', '[{"published": null, "title": "Parques de Estacionamento Públicos | Agenda Cultural de Guimarães", "url": "https://em.guimaraes.pt/geo_artigo-28/parques-de-estacionamento-publicos"}, {"published": "2025", "title": "Guia do Adepto 2025/2026 - Vitória SC (Liga Portugal)", "url": "https://ligaportugalstorage.blob.core.windows.net/backoffice/assets/Guia_do_Adepto_VSC_36368e8c3e.pdf"}, {"published": "2025-08-27", "title": "A Rota do Rei leva-te ao futebol - Vitória Sport Clube", "url": "https://vitoriasc.pt/en/2025/08/27/a-rota-do-rei-leva-te-ao-futebol/"}]', '[{"sources": [{"published": "2025-08-27", "title": "A Rota do Rei leva-te ao futebol - Vitória Sport Clube", "url": "https://vitoriasc.pt/en/2025/08/27/a-rota-do-rei-leva-te-ao-futebol/"}, {"published": "2025-08-16", "title": "Informações úteis no regresso ao Estádio D. Afonso Henriques - Vitória Sport Clube", "url": "https://vitoriasc.pt/en/2025/08/16/informacoes-uteis-no-regresso-ao-estadio-d-afonso-henriques/"}], "text": "Rota do Rei (Vitória SC e Guimabus): autocarros para o estádio a 1 € (ida e volta, pago a bordo em dinheiro). Partem de Serzedelo, Taipas e Gémeos, com cerca de 80 paragens, incluindo parques de estacionamento, e chegam à paragem sul do estádio."}]', '2026-09-15'),
  ('municipal-braga', 'Os guias do adepto indicam estacionamento limitado junto ao estádio e, como alternativa, ruas próximas ou parques pagos no centro; há autocarros especiais a 1 € e linhas TUB. Num fórum de adeptos de 2017 descrevem-se dificuldades em estacionar em dias de jogo.', '[{"published": null, "title": "Guia do Adepto - Estádio Municipal de Braga (Liga Portugal)", "url": "https://ligaportugalstorage.blob.core.windows.net/backoffice/assets/Guia_Adepto_SC_Braga_d6bdc1a8e8.pdf"}, {"published": null, "title": "Guia do Adepto – Estádio Municipal de Braga (Liga Portugal)", "url": "https://ligaportugalstorage.blob.core.windows.net/backoffice/assets/Guia_do_Adepto_SC_Braga_78ef140604.pdf"}, {"published": "2017", "title": "ESTACIONAMENTO no estádio - Fórum SuperBraga", "url": "https://arquivo.superbraga.com/forum/index.php?topic=27112.0"}]', '[{"sources": [{"published": null, "title": "Guia do Adepto - Estádio Municipal de Braga (Liga Portugal)", "url": "https://ligaportugalstorage.blob.core.windows.net/backoffice/assets/Guia_Adepto_SC_Braga_d6bdc1a8e8.pdf"}], "text": "Há autocarros especiais a 1 € para o estádio, a partir de S. Mamede d''Este, Esporões, Santa Lucrécia de Algeriz, Cabreiros, Avenida Central e Minho Center; os horários são anunciados jogo a jogo. As linhas TUB 3, 5, 9 e 95 também param perto do estádio."}]', '2026-09-15'),
  ('cidade-de-barcelos', 'Segundo o Município, o estádio tem dois parques cobertos (67 e 48 lugares), um parque exterior com 273 lugares e 117 lugares na rua junto à fachada poente. Não se encontraram regras específicas para dias de jogo.', '[{"published": null, "title": "Estádio Cidade de Barcelos | Município de Barcelos", "url": "https://www.cm-barcelos.pt/viver/desporto/estadio-cidade-de-barcelos/"}]', '[]', '2026-09-15'),
  ('22-de-junho', null, '[]', '[]', '2026-09-15'),
  ('comendador-almeida-freitas', null, '[]', '[]', '2026-09-15'),
  ('arcos', 'O guia do adepto do Rio Ave indica estacionamento gratuito na zona ribeirinha, a 10 minutos a pé, e em parques públicos e zonas residenciais. O metro (Linha B, estação Santa Clara) fica a 5–10 minutos a pé do estádio.', '[{"published": "2025", "title": "Guia do Adepto - Estádio do Rio Ave Futebol Clube 2025/2026 (Liga Portugal)", "url": "https://ligaportugalstorage.blob.core.windows.net/backoffice/assets/Guia_Adepto_RIOAVEFC_2025_2026_aacc234e11.pdf"}]', '[{"sources": [{"published": "2025", "title": "Guia do Adepto - Estádio do Rio Ave Futebol Clube 2025/2026 (Liga Portugal)", "url": "https://ligaportugalstorage.blob.core.windows.net/backoffice/assets/Guia_Adepto_RIOAVEFC_2025_2026_aacc234e11.pdf"}], "text": "Alternativa ao carro: Metro do Porto, Linha B (Vermelha), estação Santa Clara, a cerca de 5–10 minutos a pé do estádio."}]', '2026-09-15'),
  ('municipal-arouca', 'O guia do adepto do FC Arouca indica três ruas com estacionamento gratuito a 6–8 minutos a pé do estádio e estacionamento pago na Avenida das Escolas.', '[{"published": null, "title": "Guia do Adepto - Futebol Clube de Arouca (Liga Portugal)", "url": "https://ligaportugalstorage.blob.core.windows.net/backoffice/assets/Guia_Adepto_FC_Arouca_9132724c1b.pdf"}]', '[]', '2026-09-15'),
  ('fontelo', 'Em dias de jogo do Académico de Viseu, o clube recomenda os parques da Feira Semanal e da Radial de Santiago. O parque do Solar do Dão e várias ruas junto ao Complexo do Fontelo fecham, algumas desde a véspera.', '[{"published": "2026-08-27", "title": "Fan Zone estreia-se na Rua Dr. Aristides Sousa Mendes em dia de Académico X FC Porto", "url": "https://academicodeviseu.pt/noticia.php?n=1375"}, {"published": "2026-09-11", "title": "Jogo do Académico de Viseu condiciona Fontelo - Diário de Viseu", "url": "https://www.diarioviseu.pt/2026/09/11/jogo-do-academico-de-viseu-condiciona-fontelo/"}]', '[{"sources": [{"published": "2026-08-27", "title": "Fan Zone estreia-se na Rua Dr. Aristides Sousa Mendes em dia de Académico X FC Porto", "url": "https://academicodeviseu.pt/noticia.php?n=1375"}, {"published": "2026-09-11", "title": "Jogo do Académico de Viseu condiciona Fontelo - Diário de Viseu", "url": "https://www.diarioviseu.pt/2026/09/11/jogo-do-academico-de-viseu-condiciona-fontelo/"}], "text": "Em dia de jogo, a Avenida José Relvas (a partir do Pavilhão do Fontelo) fecha ao trânsito desde as 8h00. A Alameda Messias Fuschini fecha desde as 23h00 de um ou dois dias antes. O acesso só é permitido a veículos autorizados."}, {"sources": [{"published": "2026-09-11", "title": "Jogo do Académico de Viseu condiciona Fontelo - Diário de Viseu", "url": "https://www.diarioviseu.pt/2026/09/11/jogo-do-academico-de-viseu-condiciona-fontelo/"}, {"published": null, "title": "Académico de Viseu recebe FC Porto com condicionamentos no Fontelo | ViseuNow", "url": "https://viseunow.pt/academico-de-viseu-recebe-fc-porto-com-condicionamentos-no-fontelo/"}], "text": "Quando há Fan Zone na Rua Dr. Aristides de Sousa Mendes, o estacionamento nessa rua fica condicionado desde alguns dias antes do jogo e a rua fecha ao trânsito no dia do jogo."}, {"sources": [{"published": "2026-09-11", "title": "Jogo do Académico de Viseu condiciona Fontelo - Diário de Viseu", "url": "https://www.diarioviseu.pt/2026/09/11/jogo-do-academico-de-viseu-condiciona-fontelo/"}, {"published": null, "title": "Jogo entre o Académico de Viseu e o FC Porto condiciona trânsito e estacionamento no Fontelo - Jornal do Centro", "url": "https://www.jornaldocentro.pt/jogo-entre-o-academico-de-viseu-e-o-fc-porto-condiciona-transito-e-estacionamento-no-fontelo/"}], "text": "Em jogos de grande afluência, as autoridades e o clube pedem para chegar com antecedência e, se possível, ir de transportes públicos ou a pé."}]', '2026-09-15'),
  ('luz', 'O parque do estádio (Placegar, 1526 lugares) está encerrado em dias de jogo ou eventos, segundo a operadora. O guia do adepto do Benfica 25/26 sugere o Colombo, o Fonte Nova, zonas residenciais e parques EMEL próximos, e em jogos de risco a PSP fiscaliza o estacionamento nas imediações e aconselha os transportes públicos.', '[{"published": null, "title": "BENFICA ESTÁDIO – Placegar", "url": "https://placegar.com/en/park/benfica-estadio-p1-p2-p3-p5-3/"}, {"published": "2025", "title": "Guia do Adepto 25/26 – SL Benfica (Liga Portugal)", "url": "https://ligaportugalstorage.blob.core.windows.net/backoffice/assets/Documento_Guia_do_Adepto_SLB_8dca774e3f.pdf"}, {"published": null, "title": "Trânsito condicionado no domingo junto ao Estádio da Luz devido ao jogo Benfica-FCPorto (RTP)", "url": "https://www.rtp.pt/noticias/benfica/transito-condicionado-no-domingo-junto-ao-estadio-da-luz-devido-ao-jogo-benfica-fcporto_d1724182"}]', '[{"sources": [{"published": null, "title": "Trânsito condicionado no domingo junto ao Estádio da Luz devido ao jogo Benfica-FCPorto (RTP)", "url": "https://www.rtp.pt/noticias/benfica/transito-condicionado-no-domingo-junto-ao-estadio-da-luz-devido-ao-jogo-benfica-fcporto_d1724182"}, {"published": null, "title": "Trânsito condicionado no domingo junto ao Estádio da Luz devido ao jogo Benfica-FCPorto - Record", "url": "https://www.record.pt/futebol/futebol-nacional/amp/transito-condicionado-no-domingo-junto-ao-estadio-da-luz-devido-ao-jogo-benfica-fcporto"}], "text": "Em jogos de risco elevado (ex.: Benfica-FC Porto às 18h), a PSP fiscaliza o estacionamento e a circulação nas imediações desde a manhã. Há condicionamentos na Av. Condes de Carnide, na Av. Machado dos Santos, nas ruas que lá confluem e na Av. Lusíada, das 13h às 18h e das 20h30…"}, {"sources": [{"published": null, "title": "BENFICA ESTÁDIO – Placegar", "url": "https://placegar.com/en/park/benfica-estadio-p1-p2-p3-p5-3/"}], "text": "O parque do estádio fecha em dias de jogo; o P5 fecha a partir das 15h."}, {"sources": [{"published": "2025", "title": "Guia do Adepto 25/26 – SL Benfica (Liga Portugal)", "url": "https://ligaportugalstorage.blob.core.windows.net/backoffice/assets/Documento_Guia_do_Adepto_SLB_8dca774e3f.pdf"}], "text": "Zonas de «kiss & ride» para deixar passageiros: Avenida Machado Santos e Centro Comercial Colombo. O guia indica também metro (Linha Azul), comboio (Benfica, Sete Rios) e várias carreiras de autocarro."}]', '2026-09-15'),
  ('alvalade', 'O estádio tem um parque subterrâneo (Alvalade XXI, Telpark, 1315 lugares) com tarifa própria em dias de jogo. O guia do Sporting 25/26 diz que o estacionamento em dia de jogo é no piso -1 e limitado à disponibilidade. Em jogos de risco elevado há condicionamentos de trânsito, e o clube e a PSP recomendam os transportes públicos (metro do Campo Grande).', '[{"published": null, "title": "Estaciona no Parque Alvalade XXI Telpark - Lisboa", "url": "https://www.telpark.com/en/cities/lisbon/alvalade-xxi-car-park/"}, {"published": "2025", "title": "Guia do Adepto 2025/26 – Sporting Clube de Portugal (Liga Portugal)", "url": "https://ligaportugalstorage.blob.core.windows.net/backoffice/assets/Guia_do_Adepto_SCP_25_26_b1a533e853.pdf"}, {"published": "2023-12-17", "title": "Sporting-Porto é de \"risco elevado\". Saiba quais são os condicionamentos de trânsito previstos pela PSP – Observador", "url": "https://observador.pt/2023/12/17/sporting-porto-e-de-risco-elevado-saiba-quais-sao-os-condicionamentos-de-transito-previstos-pela-psp/"}]', '[{"sources": [{"published": "2025", "title": "Guia do Adepto 2025/26 – Sporting Clube de Portugal (Liga Portugal)", "url": "https://ligaportugalstorage.blob.core.windows.net/backoffice/assets/Guia_do_Adepto_SCP_25_26_b1a533e853.pdf"}], "text": "Em jogos de risco elevado há condicionamento de trânsito à volta do estádio; o Sporting recomenda ir de transportes públicos ou a pé. A saída recomendada é a estação de metro do Campo Grande; a de Telheiras também serve, exceto em jogos de risco elevado. Para TVDE, o clube acons…"}, {"sources": [{"published": "2023-12-17", "title": "Sporting-Porto é de \"risco elevado\". Saiba quais são os condicionamentos de trânsito previstos pela PSP – Observador", "url": "https://observador.pt/2023/12/17/sporting-porto-e-de-risco-elevado-saiba-quais-sao-os-condicionamentos-de-transito-previstos-pela-psp/"}], "text": "No Sporting-FC Porto de dezembro de 2023, a PSP fiscalizou o estacionamento e a circulação desde as 8h. Houve condicionamentos no Campo Grande, na Av. Padre Cruz, na Av. Rainha D. Amélia, na Rua Prof. Fernando da Fonseca e ruas vizinhas. Quem fosse de carro devia estacionar só e…"}, {"sources": [{"published": "2024-12-27", "title": "PSP explica operação e constrangimentos para o Sporting-Benfica | A Bola", "url": "https://abola.pt/futebol/noticias/psp-explica-operacao-e-constrangimentos-para-o-sporting-benfica-2024122713312727897"}], "text": "No dérbi de dezembro de 2024, a Rua António Stromp esteve fechada (trânsito alternado para moradores) e o norte do Campo Grande foi vedado para a passagem dos adeptos visitantes. Os moradores com acesso ao parque pelo helicoidal foram avisados para confirmar o acesso."}]', '2026-09-15'),
  ('jose-gomes', 'Segundo o guia do adepto do Estrela da Amadora, o estacionamento junto ao estádio é limitado, sobretudo em dias de jogo. Aconselha chegar cedo ou estacionar na Reboleira ou na Venteira e seguir a pé; a estação da Reboleira (comboio e metro) fica a cerca de 3 minutos a pé.', '[{"published": null, "title": "Guia do Adepto – Estádio José Gomes, CF Estrela da Amadora (Liga Portugal)", "url": "https://ligaportugalstorage.blob.core.windows.net/backoffice/assets/Guia_do_Adepto_Estrela_Amadora_c58283577f.pdf"}]', '[{"sources": [{"published": null, "title": "Guia do Adepto – Estádio José Gomes, CF Estrela da Amadora (Liga Portugal)", "url": "https://ligaportugalstorage.blob.core.windows.net/backoffice/assets/Guia_do_Adepto_Estrela_Amadora_c58283577f.pdf"}], "text": "Estacionamento limitado junto ao estádio, sobretudo em dias de jogo: convém chegar cedo. A estação da Reboleira (Linha de Sintra e metro, Linha Azul) fica a cerca de 3 minutos a pé."}]', '2026-09-15'),
  ('coimbra-da-mota', 'O guia do adepto do Estoril indica o Pavilhão Desportivo, a FIARTIL e os estacionamentos à volta do estádio. Um guia de viagem de 2021 diz que o estádio não tem parque próprio e que se estaciona nas ruas da Amoreira e do Bairro de São José; a estação do Estoril (Linha de Cascais) fica a 10–15 minutos a pé.', '[{"published": null, "title": "Guia do Adepto – GD Estoril Praia (Liga Portugal)", "url": "https://ligaportugalstorage.blob.core.windows.net/backoffice/assets/Estoril_Praia_GUIA_DO_ADEPTO_e5a315228a.pdf"}, {"published": "2021-07-18", "title": "Estoril Stadium - Estádio António Coimbra da Mota - Football Tripper", "url": "https://footballtripper.com/portugal/estoril-praia-stadium/"}, {"published": null, "title": "Perguntas Frequentes | Site Oficial do Estoril Praia", "url": "https://estorilpraia.pt/faqs"}]', '[{"sources": [{"published": null, "title": "Perguntas Frequentes | Site Oficial do Estoril Praia", "url": "https://estorilpraia.pt/faqs"}, {"published": null, "title": "Guia do Adepto – GD Estoril Praia (Liga Portugal)", "url": "https://ligaportugalstorage.blob.core.windows.net/backoffice/assets/Estoril_Praia_GUIA_DO_ADEPTO_e5a315228a.pdf"}], "text": "Alternativa ao carro: comboio da Linha de Cascais até ao Estoril e depois 10 a 15 minutos a pé para norte, até à Rua Dom Bosco. O guia refere também as carreiras 406 e 417 da Carris Metropolitana."}]', '2026-09-15'),
  ('complexo-alverca', 'O guia do adepto do FC Alverca lista três parques gratuitos de capacidade limitada: nas imediações do estádio, no centro de formação e no Jardim Municipal Álvaro Vidal. Em dias de eventos na zona o estacionamento junto ao estádio pode fechar, como na Feira de Natal de dezembro de 2025; a estação de Alverca fica a 15 minutos a pé.', '[{"published": null, "title": "Guia do Adepto – Futebol Clube de Alverca (Liga Portugal)", "url": "https://ligaportugalstorage.blob.core.windows.net/backoffice/assets/Guia_do_Adepto_FC_Alverca_84986a8c7f.pdf"}, {"published": "2025-12-06", "title": "COMUNICADO: Estacionamento no dia de jogo – FC Alverca SAD", "url": "https://fcalvercafutebolsad.pt/comunicado-estacionamento-no-dia-de-jogo/"}]', '[{"sources": [{"published": "2025-12-06", "title": "COMUNICADO: Estacionamento no dia de jogo – FC Alverca SAD", "url": "https://fcalvercafutebolsad.pt/comunicado-estacionamento-no-dia-de-jogo/"}], "text": "Quando há eventos junto ao estádio, o estacionamento nas imediações pode fechar todo: aconteceu no jogo de 7 de dezembro de 2025, durante a Feira de Natal. O clube publica alternativas nos seus canais."}, {"sources": [{"published": null, "title": "Guia do Adepto – Futebol Clube de Alverca (Liga Portugal)", "url": "https://ligaportugalstorage.blob.core.windows.net/backoffice/assets/Guia_do_Adepto_FC_Alverca_84986a8c7f.pdf"}], "text": "Alternativa ao carro: a estação de comboios de Alverca fica a 15 minutos a pé; há autocarros 2301, 2304, 2328, 2329 e 2842."}]', '2026-09-15'),
  ('rio-maior', 'Não se encontrou uma lista pública de parques. A Desmor, empresa municipal que gere o estádio, garantiu em 2023 e 2024 que há muitas zonas de estacionamento perto do estádio e parques sinalizados na cidade para quem vem de fora, e o guia do Casa Pia 25/26 assinala no mapa uma zona para os visitantes.', '[{"published": "2023-08-16", "title": "Empresa municipal de Rio Maior garante tudo pronto para o Casa Pia-Sporting | MAISFUTEBOL", "url": "https://maisfutebol.iol.pt/liga/casa-pia/empresa-municipal-de-rio-maior-garante-tudo-pronto-para-o-casa-pia-sporting"}, {"published": "2024-03-12", "title": "Gestão do estádio de Rio Maior e Casa Pia esperam lotação esgotada com o Benfica - Record", "url": "https://www.record.pt/futebol/futebol-nacional/liga-betclic/casa-pia/detalhe/gestao-do-estadio-de-rio-maior-e-casa-pia-esperam-lotacao-esgotada-com-o-benfica"}, {"published": "2025", "title": "Guia do Adepto 25/26 – Casa Pia AC (Liga Portugal)", "url": "https://ligaportugalstorage.blob.core.windows.net/backoffice/assets/Guia_do_Adepto_25_26_Casa_Pia_AC_c141f9ff07.pdf"}]', '[{"sources": [{"published": "2023-08-16", "title": "Empresa municipal de Rio Maior garante tudo pronto para o Casa Pia-Sporting | MAISFUTEBOL", "url": "https://maisfutebol.iol.pt/liga/casa-pia/empresa-municipal-de-rio-maior-garante-tudo-pronto-para-o-casa-pia-sporting"}], "text": "Para o Casa Pia-Sporting de agosto de 2023, a Desmor anunciou parques na cidade com placas para ajudar quem não é de Rio Maior, planeados com a GNR."}, {"sources": [{"published": "2024-03-12", "title": "Gestão do estádio de Rio Maior e Casa Pia esperam lotação esgotada com o Benfica - Record", "url": "https://www.record.pt/futebol/futebol-nacional/liga-betclic/casa-pia/detalhe/gestao-do-estadio-de-rio-maior-e-casa-pia-esperam-lotacao-esgotada-com-o-benfica"}], "text": "Em jogos com lotação esgotada (ex.: Casa Pia-Benfica, março de 2024), a gestão do estádio prepara com antecedência zonas de estacionamento perto do estádio."}]', '2026-09-15'),
  ('estadio-maritimo', 'Segundo o guia do adepto do Marítimo, o clube disponibiliza no estádio dois pisos do parque Nascente (pisos -1 e -2), a 1 € por hora. Não se encontraram avisos recentes da Câmara do Funchal ou da PSP sobre condicionamentos em dias de jogo nos Barreiros.', '[{"published": null, "title": "Guia do Adepto – Club Sport Marítimo (Liga Portugal)", "url": "https://ligaportugalstorage.blob.core.windows.net/backoffice/assets/Guia_do_Adepto_CSM_f294c47241.pdf"}]', '[{"sources": [{"published": null, "title": "Guia do Adepto – Club Sport Marítimo (Liga Portugal)", "url": "https://ligaportugalstorage.blob.core.windows.net/backoffice/assets/Guia_do_Adepto_CSM_f294c47241.pdf"}], "text": "Alternativas ao carro: carreiras 8 e 45 dos Horários do Funchal (via Barreiros), 50 e 83. Com Bolt ou Uber, a espera depois do jogo pode ser longa porque há poucos carros."}]', '2026-09-15'),
  ('madeira', 'O Estádio da Madeira tem um parque coberto de 3 pisos com 705 lugares, pago a 5 € por utilização segundo o guia do Nacional. Nos avisos de jogo de 2026 o clube diz que funcionam os pisos -2 e -3 e aconselha viaturas partilhadas, porque os lugares são limitados.', '[{"published": null, "title": "Guia do Adepto – CD Nacional (Liga Portugal)", "url": "https://ligaportugalstorage.blob.core.windows.net/backoffice/assets/Guiado_Adepto_CD_Nacional_6975ad2afd.pdf"}, {"published": "2026-05-12", "title": "Entrada gratuita para adeptos com adereços na jornada de sábado - CD Nacional", "url": "https://www.cdnacional.pt/entrada-gratuita-para-adeptos-com-aderecos-na-jornada-de-sabado/"}]', '[{"sources": [{"published": "2026-05-12", "title": "Entrada gratuita para adeptos com adereços na jornada de sábado - CD Nacional", "url": "https://www.cdnacional.pt/entrada-gratuita-para-adeptos-com-aderecos-na-jornada-de-sabado/"}, {"published": "2025-08-20", "title": "Choupana vai encher para receber o campeão nacional — DNOTICIAS.PT", "url": "https://www.dnoticias.pt/2025/8/20/460135-casa-cheia-na-choupana-para-receber-o-campeao-nacional/"}], "text": "O clube aconselha viaturas partilhadas por haver poucos lugares de estacionamento e pede que se sigam as indicações da PSP sobre o trânsito."}, {"sources": [{"published": "2025-01-02", "title": "Jogo com o FC Porto altera acessos ao Estádio da Madeira — DNOTICIAS.PT", "url": "https://www.dnoticias.pt/2025/1/2/432846-jogo-com-o-fc-porto-altera-acessos-ao-estadio-da-madeira/"}], "text": "Em jogos grandes (ex.: Nacional-FC Porto, janeiro de 2025), a partir das 15h ficou proibido estacionar no Caminho dos Pretos, no Caminho do Terço e no Caminho do Meio. O Caminho do Terço passou a sentido único descendente entre a Rotunda Dr. Nélio Ferraz Mendonça e a Rua do Poma…"}, {"sources": [{"published": null, "title": "Guia do Adepto – CD Nacional (Liga Portugal)", "url": "https://ligaportugalstorage.blob.core.windows.net/backoffice/assets/Guiado_Adepto_CD_Nacional_6975ad2afd.pdf"}], "text": "Alternativa ao carro: carreira n.º 47 dos Horários do Funchal até à paragem «Centro Hípico» e depois cerca de 1,5 km a pé (15 minutos); há também táxis, Uber e Bolt."}]', '2026-09-15'),
  ('sao-miguel', 'Há um parque de estacionamento gratuito para os adeptos junto ao Estádio de São Miguel, a norte, com acesso pela estrada Ponta Delgada–Ribeira Grande; a PSP controla o parque em frente ao estádio. Desde agosto de 2026 o Santa Clara tem autocarro gratuito para os jogos em casa, exceto com os três grandes.', '[{"published": null, "title": "Santa Clara » Accessibilities", "url": "https://cdsantaclara.com/en/acessibilidades/"}, {"published": null, "title": "Guia do Adepto – Santa Clara Açores Futebol SAD (Liga Portugal)", "url": "https://ligaportugalstorage.blob.core.windows.net/backoffice/assets/Guia_Adeptos_Santa_Clara_14f18abbd2.pdf"}, {"published": "2026-08-23", "title": "Jogos do Santa Clara passam a contar com autocarro gratuito - Açoriano Oriental", "url": "https://www.acorianooriental.pt/noticia/jogos-do-santa-clara-passam-a-contar-com-autocarro-gratuito-379830"}]', '[{"sources": [{"published": null, "title": "Clube Desportivo Santa Clara » Recomendações da PSP", "url": "https://cdsantaclara.com/recomendacoes-da-psp/"}], "text": "A PSP pede para chegar com bastante antecedência. Deve estacionar-se no parque em frente ao estádio ou nas vias de acesso afastadas do recinto, nunca nos passeios nem nos nós de acesso e saídas da via rápida."}, {"sources": [{"published": "2026-08-23", "title": "Jogos do Santa Clara passam a contar com autocarro gratuito - Açoriano Oriental", "url": "https://www.acorianooriental.pt/noticia/jogos-do-santa-clara-passam-a-contar-com-autocarro-gratuito-379830"}], "text": "Autocarro expresso gratuito para os jogos em casa, mediante apresentação do bilhete digital. Pára em Santa Clara, no centro histórico de Ponta Delgada e na Praia das Milícias e regressa 30 minutos após o apito final. Não funciona nos jogos com os três grandes."}]', '2026-09-15')
